from collections import deque

kota = {
    'Medan': ['Pekanbaru', 'Padang'],
    'Pekanbaru': ['Medan', 'Padang', 'Jambi'],
    'Padang': ['Medan', 'Pekanbaru', 'Bengkulu'],
    'Jambi': ['Pekanbaru', 'Palembang'],
    'Bengkulu': ['Padang', 'Palembang'],
    'Palembang': ['Jambi', 'Bengkulu'],
}

def bfs_jalur(g, awal, tujuan):
    q = deque([[awal]])
    dikunjungi = {awal}
    while q:
        jalur = q.popleft()
        if jalur[-1] == tujuan:
            return jalur
        for t in g[jalur[-1]]:
            if t not in dikunjungi:
                dikunjungi.add(t)
                q.append(jalur + [t])

def dfs(g, s, dikunjungi=None):
    dikunjungi = dikunjungi or []
    dikunjungi.append(s)
    for t in g[s]:
        if t not in dikunjungi:
            dfs(g, t, dikunjungi)
    return dikunjungi

print('BFS:', bfs_jalur(kota, 'Medan', 'Palembang'))
print('DFS:', dfs(kota, 'Medan'))

