from functools import lru_cache

@lru_cache(maxsize=None)
def cara_memo(n):
    if n <= 1:
        return 1
    return cara_memo(n - 1) + cara_memo(n - 2)

def cara_tabel(n):
    dp = [1] * (n + 1)
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp

print(cara_memo(10))
print(cara_tabel(10))

# kembalian koin minimum (Rupiah)
def koin_min(koin, total):
    dp = [0] + [float('inf')] * total
    for x in range(1, total + 1):
        for k in koin:
            if k <= x:
                dp[x] = min(dp[x], dp[x - k] + 1)
    return dp[total]

print('Koin untuk Rp1.300:', koin_min([100, 200, 500, 1000], 1300))

